package io.delta.kernel.types;

import io.delta.kernel.annotation.Evolving;
import java.util.Arrays;
import java.util.Objects;

/**
 * Represents the geography data type, which models geodetic (spherical) spatial data. A geography
 * value is associated with a Spatial Reference System Identifier (SRID) expressed in authority:code
 * notation (for example {@code OGC:CRS84} or {@code EPSG:4326}) and a geodetic calculation
 * algorithm.
 *
 * <p>Valid algorithms are: {@code spherical}, {@code vincenty}, {@code thomas}, {@code andoyer},
 * {@code karney}.
 *
 * <p>Two {@link GeographyType} instances are equal if and only if they have the same SRID and
 * algorithm.
 *
 * @since 4.0.0
 */
@Evolving
public final class GeographyType extends DataType {
  /** The default SRID used when none is specified. */
  public static final String DEFAULT_SRID = "OGC:CRS84";

  /** The default geodetic calculation algorithm used when none is specified. */
  public static final String DEFAULT_ALGORITHM = "spherical";

  /** The set of valid geodetic calculation algorithms. */
  private static final String[] VALID_ALGORITHMS = {
    "spherical", "vincenty", "thomas", "andoyer", "karney"
  };

  /** @return a {@link GeographyType} with the default SRID and algorithm. */
  public static GeographyType ofDefault() {
    return new GeographyType(DEFAULT_SRID, DEFAULT_ALGORITHM);
  }

  /** @return a {@link GeographyType} with the given SRID and the default algorithm. */
  public static GeographyType ofSRID(String srid) {
    return new GeographyType(srid, DEFAULT_ALGORITHM);
  }

  /** @return a {@link GeographyType} with the default SRID and the given algorithm. */
  public static GeographyType ofAlgorithm(String algorithm) {
    return new GeographyType(DEFAULT_SRID, algorithm);
  }

  private final String srid;
  private final String algorithm;

  public GeographyType(String srid, String algorithm) {
    if (!Arrays.asList(VALID_ALGORITHMS).contains(algorithm)) {
      throw new IllegalArgumentException(
          String.format(
              "Algorithm must be one of: %s", String.join(", ", VALID_ALGORITHMS)));
    }
    this.srid = srid;
    this.algorithm = algorithm;
  }

  /** @return the Spatial Reference System Identifier of this geography type. */
  public String getSrid() {
    return srid;
  }

  /** @return the geodetic calculation algorithm of this geography type. */
  public String getAlgorithm() {
    return algorithm;
  }

  @Override
  public boolean isNested() {
    return false;
  }

  @Override
  public String toString() {
    return String.format("Geography(srid=%s, algorithm=%s)", srid, algorithm);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    GeographyType that = (GeographyType) o;
    return Objects.equals(srid, that.srid) && Objects.equals(algorithm, that.algorithm);
  }

  @Override
  public int hashCode() {
    return Objects.hash(srid, algorithm);
  }
}
